  const def=StarShop.CHESTS[kind];status.textContent=found.name+(found.kind==='weapon'?' wurde deinem Waffenlager hinzugefügt.':' wurde deinem Album hinzugefügt.');refresh();render();productDialog.setAttribute('aria-label',def.name+' wird geöffnet');productDialog.replaceChildren();const title=el('h2',def.name),stage=el('div',undefined,'skin-opening-stage'),art=el('canvas',undefined,'skin-opening-chest'),label=el('p','Die Truhe erscheint …','skin-opening-status');art.width=480;art.height=320;stage.append(art);stage.dataset.chest=kind;label.setAttribute('role','status');productDialog.append(title,stage,label);productDialog.classList.add('skin-reward-dialog');productDialog.showModal();
  const reveal=StarLootReveal.SPECS[found.rarity],figure=found.kind==='skin'?skinPortrait(found.id,found.type):el('canvas');if(found.kind==='weapon'){figure.width=180;figure.height=180;figure.setAttribute('role','img');figure.setAttribute('aria-label',found.name);const image=new Image();image.onload=()=>{const c=figure.getContext('2d',{willReadFrequently:true});c.drawImage(image,0,0,180,180);c.putImageData(StarChestArt.clearBackdrop(c.getImageData(0,0,180,180)),0,0);};image.src='./shop-weapon-'+found.id+'.webp?v=154';}if(figure){figure.classList.add('skin-opening-figure');figure.hidden=true;stage.append(figure);StarLootReveal.prepare(found.rarity);}stage.style.setProperty('--reveal-color',StarSkins.RARITIES[found.rarity].color);
