 function gearPortrait(id,type){const canvas=skinPortrait(id,type);Promise.all([StarStormArt.ready,StarSkinArt.ready]).then(()=>{const c=canvas.getContext('2d'),b=StarSkinArt.portraitBounds(c.getImageData(0,0,canvas.width,canvas.height));if(!b)return;const cut=c.getImageData(b.x,b.y,b.width,b.height);canvas.width=b.width+8;canvas.height=b.height+8;canvas.getContext('2d').putImageData(cut,4,4);});return canvas;}
