 function refresh(){const visible=document.body.dataset.game==='storm';mailboxButton.hidden=!visible;if(!visible){if(productDialog.open)productDialog.close();if(dialog.open)dialog.close();}for(const id of ['armory-open','armory-shop-open'])if($(id))$(id).hidden=!visible;if($('home-diamonds'))$('home-diamonds').hidden=true;try{const profile=store().read(),pending=profile.inbox.filter(m=>!m.claimed).length;mailBadge.textContent=String(pending);mailBadge.hidden=!pending;mailboxButton.setAttribute('aria-label',pending?'Postfach öffnen · '+pending+' '+(pending===1?'Geschenk':'Geschenke'):'Postfach öffnen');globalThis.StarSkinArt?.setSelection(profile.skins?.equipped||{});if($('home-diamonds')){if(globalThis.StarInterface)StarInterface.setBalance($('home-diamonds'),profile.diamonds);else $('home-diamonds').textContent=profile.diamonds.toLocaleString('de-DE')+' Sternenstaub';}}catch(e){if($('home-diamonds'))$('home-diamonds').textContent='Waffenlager nicht erreichbar';}}
