 function award(id,score,loot){try{const result=store().settle(id,Math.floor(score),loot),lines=[];if(loot!==undefined){lines.push('Punkteverdienst: '+result.scoreDust+' Sternenstaub','Boss-Bonus: '+result.bonus.bossTotal+' Sternenstaub');for(const row of result.bonus.rows)lines.push(row.count+' × '+row.name+': +'+row.amount);lines.push('Seltene Truppenfunde: '+result.bonus.loot.regular+' × '+StarRewards.LOOT.regularAmount+' = '+result.bonus.dropTotal+' Sternenstaub','Gesamt diese Runde: '+result.roundEarned+' Sternenstaub',result.earned?'Jetzt gutgeschrieben: +'+result.earned:'Bereits gutgeschrieben','Kontostand: '+result.total+' · '+result.remainder+'/100 Restpunkte');}refresh();return {...result,text:loot!==undefined?lines.join('\n'):(result.points?result.points.toLocaleString('de-DE')+' neue Punkte → +'+result.earned+' Sternenstaub':'Bereits gutgeschrieben')+' · Gesamt '+result.total+' · '+result.remainder+'/100 Punkte zur nächsten Einheit Sternenstaub'};}catch(e){return {error:true,text:e.message};}}

